class Solution
{
public:
    int shortestWordDistance(vector< string>& wordsDict, string word1, string word2)
    {
        int a = - 1, b = - 1, best = INT_MAX;
        for (int i = 0; i < (int) wordsDict.size();++i)
        {
            if (word1 == word2)
            {
                if (wordsDict[i] == word1)
                {
                    if (a != - 1)
                    {
                        best = min(best, i - a);
                    }
                    a = i;
                }
            }
            else
            {
                if (wordsDict[i] == word1)
                {
                    a = i;
                }
                if (wordsDict[i] == word2)
                {
                    b = i;
                }
                if (a != - 1 && b != - 1)
                {
                    best = min(best, abs(a - b));
                }
            }
        }
        return best;
    }
};
